def topological_run(tasks, deps):
    """Runs tasks respecting dependencies, like an Airflow DAG scheduler,
    retrying a task once if it fails."""
    done = []
    remaining = list(tasks)
    attempts = {t: 0 for t in tasks}

    def ready(t):
        return all(d in done for d in deps.get(t, []))

    while remaining:
        progressed = False
        for t in list(remaining):
            if not ready(t):
                continue
            attempts[t] += 1
            ok = t != "transform" or attempts[t] > 1
            if ok:
                done.append(t)
                remaining.remove(t)
                print(f"task={t} status=success attempt={attempts[t]}")
            else:
                print(f"task={t} status=retry attempt={attempts[t]}")
            progressed = True
        if not progressed:
            raise RuntimeError("deadlock")
    return done

tasks = ["extract", "transform", "load"]
deps = {"transform": ["extract"], "load": ["transform"]}
order = topological_run(tasks, deps)
print("execution order:", order)
